void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  float d = distance(fragCoord, iMouse.xy);
  float ring = smoothstep(30.0, 28.0, d) * step(1.0, iMouse.z + 1.0);
  fragColor = vec4(uv * 0.3, 0.0, 1.0) + vec4(ring, ring * step(0.0, iMouse.z), 0.0, 0.0);
}
